-- A25: metadados privados mínimos de upload; sem URL permanente, nome de arquivo ou conteúdo documental.
alter table public.subdivision_buyer_attachment_intents add column storage_key text unique,add column content_type text check(content_type in ('application/pdf','image/jpeg','image/png')),add column byte_size integer check(byte_size between 1 and 2097152),add column uploaded_at timestamptz;
create or replace function public.subdivision_record_buyer_attachment_upload(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text,p_attachment_intent_id uuid,p_storage_key text,p_content_type text,p_byte_size integer,p_correlation_id uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare v_existing uuid;begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);select target_id into v_existing from public.admin_audit_events where command_name='subdivision_record_buyer_attachment_upload' and correlation_id=p_correlation_id and outcome='allowed' limit 1;if v_existing is not null then return v_existing;end if;update public.subdivision_buyer_attachment_intents set storage_key=p_storage_key,content_type=p_content_type,byte_size=p_byte_size,uploaded_at=now() where id=p_attachment_intent_id and organization_id=p_organization_id and storage_key is null returning id into v_existing;if v_existing is null then raise exception using errcode='42501',message='SUBDIVISION_ATTACHMENT_UPLOAD_CONTEXT_DENIED';end if;insert into public.admin_audit_events(correlation_id,actor_user_id,organization_id,command_name,outcome,target_type,target_id,payload_redacted)values(p_correlation_id,p_actor_user_id,p_organization_id,'subdivision_record_buyer_attachment_upload','allowed','subdivision_buyer_attachment_intent',v_existing,jsonb_build_object('module',p_module::text,'purpose_code',trim(p_purpose_code),'upload_recorded',true));return v_existing;end;$$;revoke all on function public.subdivision_record_buyer_attachment_upload(uuid,uuid,public.operating_module,text,uuid,text,text,integer,uuid) from public,anon,authenticated;grant execute on function public.subdivision_record_buyer_attachment_upload(uuid,uuid,public.operating_module,text,uuid,text,text,integer,uuid) to service_role;
